qss:
QWidget { background: #111318; color: #f2f4f7; font-family: "Segoe UI", "Inter", sans-serif; font-size: 10pt; }
QMainWindow, QDialog { background: #111318; }
QLabel { background: transparent; }
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface { background: #191d24; border: 1px solid #344054; border-radius: 16px; }
QLabel#TitleLabel { font-size: 16pt; font-weight: 700; color: #f2f4f7; }
QLabel#SubtleLabel { color: #98a2b3; }
QPushButton { background: #252b36; color: #f2f4f7; border: 1px solid #344054; border-radius: 12px; padding: 8px 12px; }
QPushButton:hover { background: #303846; }
QPushButton#AccentButton { background: #4f7cff; border: 1px solid #6b91ff; color: #ffffff; font-weight: 700; }
QPushButton#AccentButton:hover { background: #6b91ff; }
QPushButton#DangerButton { background: #4b2228; }
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser, QSpinBox { background: #0e1117; color: #f2f4f7; border: 1px solid #344054; border-radius: 12px; padding: 8px; }
QListWidget::item { border-radius: 10px; padding: 8px; margin: 2px; }
QListWidget::item:selected { background: #24334a; border: 1px solid #4f7cff; }
QScrollArea { border: none; background: transparent; }
QScrollBar:vertical { background: #191d24; width: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:vertical { background: #344054; min-height: 32px; border-radius: 7px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QProgressBar { border: 1px solid #344054; border-radius: 10px; background: #0e1117; text-align: center; min-height: 18px; }
QProgressBar::chunk { background: #4f7cff; border-radius: 8px; }
QFrame#AssistantBubbleCard { background: #191d24; border: 1px solid #344054; border-left: 4px solid #6b91ff; border-radius: 16px; }
QFrame#UserBubbleCard { background: #24334a; border: 1px solid #344054; border-radius: 16px; }
